import{_ as i,l as r,o as e,c as l,v as s,p as n,x as t,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"表调度","description":"","frontmatter":{"title":"表调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/list-scheduling.md","filePath":"cs/list-scheduling.md","lastUpdated":1789023840000}'),p={name:"cs/list-scheduling.md"};function u(_,a,m,f,A,E){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=s('<h1 id="表调度" tabindex="-1">表调度 <a class="header-anchor" href="#表调度" aria-label="Permalink to &quot;表调度&quot;">​</a></h1><div class="epigraph"><p>在数据相关 DAG 上维护就绪表，按优先级发下一条指令。块内表调度是后端调度的基线，不保证全局最优。</p><footer>—— 据 Hennessy and Gross, 1983；Gibbons and Muchnick；龙书 8.10；对照主干[指令调度](/cs/instruction-sched) 整理</footer></div><p>上一课<a href="/cs/coalescing-splitting">合并与拆分</a>改了区间与可能的 <code>mov</code>。主干调度课已给 DAG。缺口是进阶：<strong>优先级函数</strong>（高度、延迟、寄存器压力）、分配前 vs 后调度、与线性扫描的交互。本课钉 list scheduling，软件流水下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>选择后的指令有延迟。就绪队列：入度为 0。选谁：最长路径优先、或减压力。缺口是<strong>启发式表</strong>，不是再定义真相关。</p><p>分配后：物理寄存器引入反相关，可能要再调度。分配前：虚拟名，压力估计用「当前活着的名」。</p><h3 id="表调度不是-tomasulo" tabindex="-1">表调度不是 Tomasulo <a class="header-anchor" href="#表调度不是-tomasulo" aria-label="Permalink to &quot;表调度不是 Tomasulo&quot;">​</a></h3><p>硬件动态调度运行时醒；本课静态排序。组成课超标量不替代编译器排 VLIW 槽。</p><p><span class="marginnote">Hennessy–Gross。龙书。Muchnick 8 章。本课块内；追踪调度点名 Fisher。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建 DAG。拓扑：就绪表。循环发指令、更新。延迟槽目标插有效指令或 nop。</p>',11)),(e(),n(h,null,{default:t(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DAG%5B%22%E7%9B%B8%E5%85%B3%20DAG%22%5D%20--%3E%20RDY%5B%22%E5%B0%B1%E7%BB%AA%E8%A1%A8%22%5D%0A%20%20RDY%20--%3E%20PICK%5B%22%E4%BC%98%E5%85%88%E7%BA%A7%E9%80%89%E5%8F%96%22%5D%0A%20%20PICK%20--%3E%20SEQ%5B%22%E5%8F%91%E5%B0%84%E5%BA%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<p>与展开：更大块更好调度。与向量化：向量指令延迟不同，表要认。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最优调度难。表调度可能填不满。寄存器压力优先可能拉长关键路径。不要在有副作用的 store 上无视别名边。</p><p>调度与 fast-math 无关，但与 load 投机（移过分支）有关，须安全。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写整数线性规划最优调度。后课默认：块内用表调度。下一课软件流水：循环核的模调度。</p><p>也不把表调度当操作系统调度器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>表调度：就绪表 + 优先级，块内排延迟。</li><li>分配前后各做一次是常见流水。</li><li>启发式，非最优。</li><li>出处：Hennessy and Gross, 1983；龙书；Muchnick。</li></ul>',9))])}const T=i(p,[["render",u]]);export{b as __pageData,T as default};
